Investigation
Current state
Let's look at the below code snippet:



      pytorch/aten/src/ATen/native/cuda/SoftMax.cu


        Lines 846 to 880
      in
      1664033







           if (!half_to_float) { 




             auto output_ptr = output.mutable_data_ptr<scalar_t>(); 




             auto input_ptr = input.const_data_ptr<scalar_t>(); 




             if (dim_size <= 1024 && dim_size*sizeof(scalar_t) <= 4096) { 




               int64_t remaining = outer_size; 




               int64_t chunk_size = (1L << 30L) / dim_size; 




               while(remaining > 0) { 




                 dispatch_softmax_forward<scalar_t, scalar_t, accscalar_t, is_log_softmax, false>( 




                   output_ptr, input_ptr, dim_size, dim_size, std::min<int64_t>(remaining, chunk_size), nullptr/* not masked */); 




                 input_ptr += chunk_size * dim_size; 




                 output_ptr += chunk_size * dim_size; 




                 remaining -= chunk_size; 




               } 




             } else { 




               constexpr int ILP = sizeof(float4) / sizeof(scalar_t); 




               dim3 block = SoftMaxForward_getBlockSize(dim_size); 




               size_t smem_reduction_sz = block.x / C10_WARP_SIZE * sizeof(accscalar_t); 




               auto max_elements_per_smem = (at::cuda::getCurrentDeviceProperties()->sharedMemPerBlock - 




                 smem_reduction_sz) / sizeof(scalar_t); 









               bool can_use_smem = (size_t) dim_size < max_elements_per_smem; 




               can_use_smem &= !(reinterpret_cast<uintptr_t>(input_ptr) % ALIGN_BYTES); 




               can_use_smem &= (!(reinterpret_cast<uintptr_t>(output_ptr) % ALIGN_BYTES)); 




               can_use_smem &= !(dim_size % ILP); 









               if (can_use_smem) { 




                 size_t smem_sz = dim_size * sizeof(scalar_t) + smem_reduction_sz; 




                 cunn_SoftMaxForwardSmem<ILP, scalar_t, accscalar_t, scalar_t, Epilogue> 




                   <<<grid, block, smem_sz, stream>>>(output_ptr, input_ptr, dim_size); 




               } else { 




                 cunn_SoftMaxForward<ILP, scalar_t, accscalar_t, scalar_t, Epilogue> 




                   <<<grid, block, smem_reduction_sz, stream>>>(output_ptr, input_ptr, dim_size); 




               } 









               C10_CUDA_KERNEL_LAUNCH_CHECK(); 





There are two kinds of softmax op in CUDA:

dispatch_softmax_forward
cunn_SoftMaxForwardSmem or cunn_SoftMaxForward

The implementation of cunn_SoftMaxForwardSmem or cunn_SoftMaxForward will be invoked if N>1024, but it's not efficient in the rough range 1025~2000.
root cause
The reason why the cunn_SoftMaxForwardSmem and cunn_SoftMaxForward is not efficient is too much global memory and share memory access, because they didn't cache the data each thread would like to access in register, so they may have to load data from memory much times.
Alternatives
We could try to use registers to cache the data which a thread would like to use.
Pros:
Improve performance by reducing memory access
Cons:
Increase register pressure, but we could just do it in range of N in about 1025~2000, which may just increase about 1~2 register for a thread (I guess it's acceptable).
Now I have a draft implement in my local, it shows ~50% performance gain compared with current torch, for the above case, its output is:
